import{_ as t,o as s,c as a,a0 as i}from"./chunks/framework.D4fUSYzX.js";const u=JSON.parse('{"title":"ADR 0029: Security tickets synthesize severity as labels","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0029-security-tickets-synthesize-severity-as-labels.md","filePath":"adr/0029-security-tickets-synthesize-severity-as-labels.md"}'),r={name:"adr/0029-security-tickets-synthesize-severity-as-labels.md"};function o(n,e,c,l,h,d){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0029-security-tickets-synthesize-severity-as-labels" tabindex="-1">ADR 0029: Security tickets synthesize severity as labels <a class="header-anchor" href="#adr-0029-security-tickets-synthesize-severity-as-labels" aria-label="Permalink to &quot;ADR 0029: Security tickets synthesize severity as labels&quot;">​</a></h1><p>Status: accepted Date: 2026-09-16</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Three of the security ticket sources carry no labels on GitHub. A repository security advisory carries a severity, a Dependabot alert carries one on its embedded security advisory, and a secret scanning alert carries neither. The factory ranks tickets through the Priority label list and matches task rules on label sets, so a severity that never reaches the label set cannot rank a ticket and a rule cannot target it. For issues and pull requests every label is an external fact the control plane only reads; the security item types have no label slot to put the severity in, so the source must decide what the ticket&#39;s label set carries.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>The source synthesizes one label per security ticket from its severity fact.</strong> A security advisory and a Dependabot alert take the bare severity word as their single label: <code>critical</code>, <code>high</code>, <code>medium</code>, or <code>low</code>; an item with no severity takes none. An open secret scanning alert takes the label <code>critical</code>: an exposed credential stays live until it is rotated, so it ranks at the top of the list while it is open.</p><p><strong>The synthesized label is a source fact, not a writable label.</strong> A refresh can change it when the severity changes, and a ticket that leaves the source list drops it with the ticket. The control plane never writes it to the external source: none of the three item types takes labels on GitHub, and the shipped task types of the security kinds write no transition labels on their tickets.</p><p>The bare word is deliberate, against a prefixed name such as <code>severity-critical</code>: the Priority label list the Default configuration ships already names <code>critical</code>, <code>high</code>, and <code>low</code>, so a security ticket ranks the moment its source is configured, with no operator edit. A severity the list does not name (the default list omits <code>medium</code>) ranks no ticket, exactly as an unlabeled issue does; the operator extends the list when they want that rank.</p>',8)])])}const p=t(r,[["render",o]]);export{u as __pageData,p as default};
